const body = $input.first().json.body ?? {};
const data = body.data ?? {};
const key = data.key ?? {};

// Número autorizado — configure localmente no n8n
const NUMERO_AUTORIZADO = 'COLOQUE_SEU_NUMERO_AQUI';

// Identifica o número pela conversa, não pelo body.sender
const numeroRemetente = String(
  key.remoteJidAlt ?? key.remoteJid ?? ''
)
  .split('@')[0]
  .replace(/\D/g, '');

const numeroAutorizado = NUMERO_AUTORIZADO.replace(/\D/g, '');

const remoteJid = String(key.remoteJid ?? '');

// 1. Ignora mensagens enviadas pelo próprio bot
if (key.fromMe === true) {
  return [];
}

// 2. Aceita somente conversas privadas
if (!remoteJid.endsWith('@s.whatsapp.net')) {
  return [];
}

// 3. Bloqueia se o número autorizado não estiver configurado
if (!numeroAutorizado) {
  return [];
}

// 4. Aceita somente o número autorizado
if (numeroRemetente !== numeroAutorizado) {
  return [];
}

// 5. Extrai o texto da mensagem
const texto =
  data.message?.conversation ??
  data.message?.extendedTextMessage?.text ??
  '';

const textoLimpo = texto.trim();

if (!textoLimpo) {
  return [];
}

// 6. Normaliza para aceitar CARDÁPIO ou CARDAPIO
const textoNormalizado = textoLimpo
  .normalize('NFD')
  .replace(/\p{Diacritic}/gu, '');

if (!/^CARDAPIO\b/i.test(textoNormalizado)) {
  return [];
}

// 7. Remove a palavra-chave antes de enviar para a IA
const mensagemParaIA = textoLimpo
  .replace(/^CARD[ÁA]PIO\b[\s:,-]*/i, '')
  .trim();

if (!mensagemParaIA) {
  return [];
}

// 8. Entrega os dados aos próximos nodes
return [{
  json: {
    instancia: body.instance ?? '',
    texto: mensagemParaIA,
    chatId: numeroAutorizado,
    numeroSender: numeroRemetente,
    fromMe: false
  }
}];

