const menu = $('Extrai cardápio').first().json.output ?? {};

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

// Recebe somente as proteínas extraídas pelo Gemini
const proteinas = Array.isArray(menu.proteinas)
  ? menu.proteinas
  : [];

if (proteinas.length === 0) {
  throw new Error(
    'Nenhuma proteína foi identificada. Verifique a mensagem enviada e a extração do Gemini.'
  );
}

// Monta os cartões das proteínas
const categoriasHtml = `
  <div class="categoria">
    <div class="itens">
      ${proteinas.map((proteina) => `
        <div class="item">
          <div class="item-nome">${esc(proteina)}</div>
        </div>
      `).join('')}
    </div>
  </div>
`;

const data = String(menu.data ?? '').trim()
  ? esc(menu.data)
  : new Date().toLocaleDateString('pt-BR', {
      timeZone: 'America/Fortaleza',
      day: '2-digit',
      month: 'long',
      year: 'numeric'
    });

const restaurante = esc(menu.estabelecimento || 'Restaurante');

const titulo = esc(menu.titulo || 'Cardápio de Hoje');

// HTML completo do cardápio
const template = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Cardápio do Dia</title>
<style>
*{box-sizing:border-box}
body{margin:0;padding:28px;background:#fff7ed;font-family:Arial,Helvetica,sans-serif;color:#263238}
#cardapio{width:100%;max-width:1024px;margin:auto;background:#fff;border-radius:28px;overflow:hidden;box-shadow:0 12px 35px #713f121c}
.cabecalho{padding:48px 42px;text-align:center;color:white;background:linear-gradient(135deg,#f97316,#dc2626)}
.selo{display:inline-block;padding:8px 18px;border-radius:30px;background:#ffffff30;font-weight:bold;letter-spacing:1px;text-transform:uppercase;font-size:14px}
h1{font-size:54px;line-height:1.05;margin:20px 0 10px}
.restaurante{font-size:24px;font-weight:bold}
.data{font-size:18px;margin-top:12px}
.conteudo{padding:34px 42px}
h2{font-size:30px;color:#c2410c;margin:0 0 20px}
.informacoes-fixas{background:#fff7ed;border:2px solid #fed7aa;border-radius:22px;padding:26px;margin-bottom:32px}
.precos{display:flex;gap:18px;flex-wrap:wrap}
.preco-card{flex:1;min-width:230px;background:white;border-radius:18px;padding:22px;border:1px solid #fdba74}
.preco-card h3{margin:0 0 8px;font-size:23px;color:#9a3412}
.preco{font-size:34px;font-weight:800;color:#ea580c;margin:8px 0}
.preco-card p{margin:0;font-size:17px}
.acompanhamentos{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}
.acompanhamento{background:#dcfce7;color:#166534;padding:10px 16px;border-radius:30px;font-weight:bold;font-size:16px}
.categoria{margin:26px 0}
.categoria h3{font-size:25px;color:#166534;border-bottom:3px solid #bbf7d0;padding-bottom:10px}
.itens{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.item{background:#fff7ed;border-radius:15px;padding:18px;border-left:6px solid #f97316}
.item-nome{font-size:21px;font-weight:bold}
.observacoes{margin-top:28px;padding:20px;background:#fef3c7;border-radius:16px;font-size:17px}
.rodape{text-align:center;padding:24px;background:#14532d;color:white;font-weight:bold;font-size:18px}
@media(max-width:650px){.cabecalho{padding:34px 20px}h1{font-size:40px}.conteudo{padding:26px 20px}.itens{grid-template-columns:1fr}.precos{display:block}.preco-card{margin-bottom:12px}}
.acompanhamentos-destaque{margin-top:30px;padding:28px;background:#14532d;border:4px solid #86efac;border-radius:22px;box-shadow:0 8px 20px #14532d24}
.acompanhamentos-destaque h2{color:#fff;font-size:32px;margin-bottom:8px}
.acompanhamentos-subtitulo{color:#dcfce7;font-size:18px;font-weight:bold;margin:0 0 18px}
.acompanhamentos-destaque .acompanhamento{background:#fff;color:#14532d;border:2px solid #bbf7d0;padding:13px 20px;font-size:19px;font-weight:800;box-shadow:0 2px 5px #00000018}
.proteinas-dia{margin-bottom:34px}
</style>
</head>
<body>
<div id="cardapio">
<header class="cabecalho">
<div class="selo">Sabor do dia</div>
<h1>${titulo}</h1>
<div class="restaurante">${restaurante}</div>
<div class="data">${data}</div>
</header>

<main class="conteudo">

<section class="informacoes-fixas">
<h2>Monte sua marmita</h2>
<div class="precos">
<div class="preco-card">
<h3>Marmita pequena</h3>
<div class="preco">R$ 13,00</div>
<p>Escolha 1 opção de proteína</p>
</div>
<div class="preco-card">
<h3>Marmita grande</h3>
<div class="preco">R$ 15,00</div>
<p>Escolha 2 opções de proteína</p>
</div>
</div>
</section>

<section class="informacoes-fixas">
<section class="proteinas-dia">
<h2>Escolha suas proteínas</h2>
${categoriasHtml}
</section>
</section>

<section class="acompanhamentos-destaque">
<h2>Escolha seus acompanhamentos</h2>
<p class="acompanhamentos-subtitulo">Você também pode escolher seus acompanhamentos favoritos:</p>
<div class="acompanhamentos">
<span class="acompanhamento">Arroz</span>
<span class="acompanhamento">Feijão</span>
<span class="acompanhamento">Salada verde</span>
<span class="acompanhamento">Salada de maionese</span>
<span class="acompanhamento">Farofa</span>
<span class="acompanhamento">Cuscuz</span>
</div>
</section>

</main>
<footer class="rodape">Feito com carinho para você!</footer>
</div>
</body>
</html>
`;

return [{
  json: {
    html: template
  }
}];

const html = $input.first().json.html;
if (!html) throw new Error('HTML do cardápio não foi gerado.');

return [{
  json: {},
  binary: {
    data: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html'
    }
  }
}];

const bin = $input.first().binary?.data;

if (!bin) {
  throw new Error('Imagem do cardápio não foi gerada.');
}

const buffer = await helpers.getBinaryDataBuffer(0, 'data');
const original = $('Filtrar mensagem').first().json;

const restaurante = 'Restaurante';

return [{
  json: {
    number: original.chatId,
    mediatype: 'image',
    mimetype: 'image/jpeg',
    fileName: 'cardapio.jpg',
    caption: `Cardápio de hoje — ${restaurante} 🍽️`,
    media: buffer.toString('base64')
  }
}];
